heart=[('right-atrium','Right atrium','outer','Receives oxygen-poor blood returning from the body.'),('left-atrium','Left atrium','outer','Receives oxygen-rich blood returning from the lungs.'),('right-ventricle','Right ventricular cavity','chambers','The right ventricle pumps blood toward the lungs. This mesh represents its cavity boundary, not its muscular wall.'),('left-ventricle','Left ventricular cavity','chambers','The left ventricle pumps blood into the aorta. This mesh represents its cavity boundary, not its muscular wall.'),('ventricular-wall','Ventricular wall','outer','Muscle surrounding the ventricles contracts to pump blood.'),('septum','Interventricular septum','inner','The muscular partition separates the ventricles. No independent source mesh is available here.'),('tricuspid','Tricuspid valve','valves','Between right atrium and right ventricle; helps prevent backward flow.'),('mitral','Mitral valve','valves','Between left atrium and left ventricle; helps prevent backward flow.'),('pulmonary','Pulmonary valve','valves','Between right ventricle and pulmonary trunk.'),('aortic','Aortic valve','valves','Between left ventricle and aorta.'),('aorta','Aorta','vessels','Carries oxygen-rich blood into the systemic circulation.'),('svc','Superior vena cava','vessels','Returns blood from the upper body to the right atrium.'),('ivc','Inferior vena cava','vessels','Returns blood from the lower body to the right atrium.'),('pulmonary-arteries','Pulmonary trunk and arteries','vessels','Carry oxygen-poor blood from the right ventricle toward the lungs.'),('pulmonary-veins','Pulmonary veins','vessels','Return oxygen-rich blood from the lungs to the left atrium.'),('coronary','Coronary arteries','vessels','Supply the heart muscle itself.')]
