def condition(id,name,anatomy,summary,symptoms,treatment,sources,catalog=[],drugs=[]):return dict(id=id,name=name,anatomy=anatomy,summary=summary,symptoms=symptoms,treatment=treatment,sources=sources,catalogRefs=catalog,drugRefs=drugs,_review='pending')
hc=[condition('aortic-dissection','Aortic dissection',['aorta'],'Blood enters the wall of the aorta and separates its layers. Location, extent and treatment differ between cases.',['Sudden severe chest or back pain','Symptoms vary'],'The existing exhibit shows true and false lumens. Repair may replace an affected segment or exclude an entry tear in selected cases; no universal repair is implied.',['https://pmc.ncbi.nlm.nih.gov/articles/PMC9860464/']),condition('coronary-artery-disease','Coronary artery disease',['coronary'],'Plaque can narrow coronary arteries and limit blood supply to heart muscle.',['Chest discomfort','Shortness of breath'],'Risk-factor care, medicines and selected procedures address different aspects of disease.',['https://www.nhlbi.nih.gov/health/coronary-heart-disease'],['stable-angina'],['atorvastatin','nitroglycerin']),condition('myocardial-infarction','Myocardial infarction',['coronary','ventricular-wall'],'A sudden loss of blood supply can damage heart muscle. The highlighted wall is context, not an individual infarct map.',['Chest discomfort','Breathlessness','Symptoms may be atypical'],'Emergency treatment aims to restore blood supply and limit injury.',['https://www.nhlbi.nih.gov/health/heart-attack']),condition('heart-failure','Heart failure',['ventricular-wall'],'The heart cannot fill or pump adequately for the body’s needs. Different forms have different mechanisms.',['Breathlessness','Fatigue','Swelling'],'Medicines, lifestyle support and selected devices or procedures depend on the type of heart failure.',['https://www.nhlbi.nih.gov/health/heart-failure'],['heart-failure']),condition('aortic-stenosis','Aortic stenosis',['aortic','left-ventricle'],'A narrowed aortic valve obstructs outflow from the left ventricle.',['Breathlessness','Chest discomfort','Fainting'],'Severe symptomatic disease may require valve replacement; medicines do not remove the valve obstruction.',['https://www.nhlbi.nih.gov/health/heart-valve-diseases']),condition('mitral-regurgitation','Mitral regurgitation',['mitral','left-atrium'],'Incomplete mitral valve closure allows blood to leak backward during ventricular contraction.',['Breathlessness','Fatigue'],'Management depends on the cause and severity and may include valve repair or replacement.',['https://www.nhlbi.nih.gov/health/heart-valve-diseases'])]
bc=[condition('alzheimers','Alzheimer’s disease',['hippocampus','temporal','parietal'],'Alzheimer’s involves changes in proteins, synapses and neurons across networks. Its course varies between individuals.',['Memory difficulties','Changes in thinking and daily function'],'Symptom-directed medicines and selected early-disease amyloid therapies address different mechanisms. Eligibility and monitoring require specialist assessment.',[alz,alzt]),condition('parkinsons','Parkinson’s disease',['basal-ganglia','brainstem'],'Loss of dopamine-producing neurons disrupts movement circuits. Highlighted structures are circuit context, not an exact lesion map.',['Slowness','Stiffness','Tremor'],'Dopamine-related medicines, rehabilitation and selected procedures can help symptoms. Dedicated medicines are not yet in this catalog.',['https://www.ninds.nih.gov/current-research/focus-disorders/parkinsons-disease-research/parkinsons-disease-challenges-progress-and-promise']),condition('ischemic-stroke','Ischemic stroke',['cerebral-arteries'],'An arterial blockage reduces blood supply to part of the brain. Effects depend on the territory and duration.',['Sudden weakness','Speech or vision changes'],'Emergency assessment identifies candidates for clot-dissolving medicine or clot retrieval. Alteplase is a catalog example, not appropriate for every stroke.',[stroke],[],['alteplase']),condition('hemorrhagic-stroke','Hemorrhagic stroke',['cerebral-arteries'],'Bleeding in or around the brain can injure tissue and raise pressure. This model does not show an individual hemorrhage.',['Sudden neurological symptoms','Severe headache may occur'],'Emergency care differs from ischemic stroke; clot-dissolving drugs do not treat brain bleeding.',[stroke]),condition('epilepsy','Epilepsy',['frontal','temporal'],'Recurrent seizures arise from abnormal electrical activity in brain networks. Many different regions and causes can be involved.',['Seizures','Altered awareness in some seizures'],'Antiseizure medicines and selected non-drug approaches can help. Highlighted lobes are examples, not exclusive origins.',['https://www.ninds.nih.gov/health-information/disorders/epilepsy-and-seizures'],['epilepsy']),condition('multiple-sclerosis','Multiple sclerosis',['corpus-callosum','brainstem'],'Immune-mediated injury affects myelin and nerve fibers in the central nervous system. Brain and spinal cord involvement varies.',['Sensory changes','Weakness','Visual symptoms'],'Disease-modifying therapy differs from symptom relief. Baclofen in this catalog addresses spasticity; it does not modify the disease.',['https://www.ninds.nih.gov/health-information/disorders/multiple-sclerosis'],['multiple-sclerosis'])]
