 r[id]=dict(id=id,name=id.title(),classification='Cardiovascular system · muscular organ' if id=='heart' else 'Central nervous system · encephalon',asset=f'/models/organs/{id}.glb',assetVersion='bp3d-4.0-extracted-v1',referenceBody='male',referenceNote='Shared BodyParts3D adult-male organ reference, opened from either body. This is not a sex-specific organ reconstruction.',structures=[dict(id=i,name=n,layer=l,description=d,sources=[flow if id=='heart' else brain],parentId=None,_review='pending',available=False,sourceIds=[],fmaIds=[])for i,n,l,d in structs],layers=['all','outer','chambers','valves','vessels']if id=='heart' else ['all','outer','inner','vessels'],availableAnimations=['cycle','flow']if id=='heart' else ['signal'],conditions=conditions,sources=[flow]if id=='heart' else [brain,alz],validation=dict(geometry='Retained registered source surfaces',medicalReview='pending',animation='Educational schematic, not measured motion'),attribution=dict(text='BodyParts3D © DBCLS · CC BY 4.0',url='https://dbarchive.biosciencedbc.jp/en/bodyparts3d/lic.html'))
